const P = '<CORREO>';
const saludo = 'Buenos días, les enviamos la factura del pedido. Quedamos atentos.';
const c = (caso, esperado, correo_id, fecha_hora, de, adjunto, extra = {}) =>
  ({ json: { caso, esperado, correo_id, fecha_hora, de, para: P, asunto: 'Factura ' + adjunto, cuerpo: saludo, adjunto, ...extra } });
// En orden: la original (caso 7) antes que su duplicada (caso 8), y el caso 11 repite el 2.
return [
  c('1 PDF con QR', 'Recibida, fuente qr', 'COR-003', '2026-10-06 12:22', '<CORREO>', 'LOTE-003.pdf'),
  c('2 PDF sin QR', 'Recibida, fuente texto', 'COR-002', '2026-10-26 17:24', '<CORREO>', 'LOTE-002.pdf'),
  c('3 escaneado sin QR', 'Recibida, fuente ocr', 'COR-048', '2026-10-16 08:57', '<CORREO>', 'LOTE-048.pdf'),
  c('4 fecha en otro formato (21-10-26)', 'Recibida, fecha 2026-10-21', 'COR-131', '2026-10-22 16:37', '<CORREO>', 'LOTE-131.pdf'),
  c('5 CUIT inválido', 'En cola, CUIT impreso distinto del QR', 'COR-024', '2026-10-16 16:22', '<CORREO>', 'LOTE-024.pdf'),
  c('6 total que no cierra', 'En cola, el total no cierra', 'COR-135', '2026-10-28 17:33', '<CORREO>', 'LOTE-135.pdf'),
  c('7 original de una duplicada', 'Recibida', 'COR-090', '2026-10-29 09:12', '<CORREO>', 'LOTE-090.pdf'),
  c('8 duplicada con número cambiado', 'En cola prioridad alta, posible duplicada de LOTE-090', 'COR-151', '2026-10-28 17:10', '<CORREO>', 'LOTE-151.pdf'),
  c('9 monotributista, PDF con texto', 'Recibida, Factura C, IVA 0, PRV-121', 'PRUEBA-MONO-1', '2026-10-15 10:00', '<CORREO>', 'MONO-PRV-121.pdf', { carpeta: 'pruebas_extra' }),
  c('10 monotributista, escaneado', 'Recibida, Factura C, IVA 0, PRV-122', 'PRUEBA-MONO-2', '2026-10-17 10:00', '<CORREO>', 'MONO-PRV-122.pdf', { carpeta: 'pruebas_extra' }),
  c('11 el mismo comprobante otra vez', 'Ya registrado antes, sin nueva fila en la cola', 'COR-002', '2026-10-26 17:24', '<CORREO>', 'LOTE-002.pdf'),
];

// Cada corrida usa su propio prefijo: las filas de prueba no se mezclan con las reales ni con otras corridas.
const n = new Date(), z = (x) => String(x).padStart(2, '0');
const prefijo = `PRUEBA-${n.getFullYear()}${z(n.getMonth() + 1)}${z(n.getDate())}${z(n.getHours())}${z(n.getMinutes())}${z(n.getSeconds())}-`;
return $input.all().map((i) => ({ json: { ...i.json, prefijo_id: prefijo } }));

const casos = $('CA84bP_Casos').all().map((i) => i.json);
const a = $('CA84bP_Llamar_8.4a').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
const m = (r) => (r.motivos || []).join('; ');
const ok = [
  (r) => r.estado === 'Recibida' && r.fuentes.total === 'qr',
  (r) => r.estado === 'Recibida' && r.fuentes.total === 'texto',
  (r) => r.estado === 'Recibida' && r.fuentes.total === 'ocr',
  (r) => r.estado === 'Recibida' && r.datos.fecha === '2026-10-21',
  (r) => r.estado === 'En cola de revisión' && /CUIT impreso/.test(m(r)),
  (r) => r.estado === 'En cola de revisión' && /no cierra/.test(m(r)),
  (r) => r.estado === 'Recibida',
  (r) => r.estado === 'En cola de revisión' && r.posible_duplicada === true && /LOTE-090/.test(m(r)),
  (r) => r.estado === 'Recibida' && r.datos.tipo === 'Factura C' && r.datos.iva === 0 && r.proveedor_id === 'PRV-121',
  (r) => r.estado === 'Recibida' && r.datos.tipo === 'Factura C' && r.datos.iva === 0 && r.proveedor_id === 'PRV-122',
  (r) => r.estado === 'Ya registrado antes' && r.registrado === false,
];
return casos.map((c, i) => { const r = res[i] || {};
  let pasa = false; try { pasa = a[i].estado === 'recibido' && ok[i](r); } catch (e) {}
  return { json: { caso: c.caso, esperado: c.esperado, resultado: pasa ? 'PASA' : 'FALLA',
    detalle: JSON.stringify({ recepcion: a[i] && a[i].estado, tipo: r.datos && r.datos.tipo, estado: r.estado, proveedor: r.proveedor_id,
      fecha: r.datos && r.datos.fecha, total: r.datos && r.datos.total, fuente_total: r.fuentes && r.fuentes.total, motivos: m(r) }) } }; });
